-- =====================================================================
--  59_bank_edebiyyat10.sql : EDEBIYYAT 10 BANKI
--
--  BU FAYL ELLE YAZILMIR - tools/edebiyyat10.py yaradir:
--      python3 tools/edebiyyat10.py
--
--  8 movzu x 31 sual = 248.  Her movzuda 4 asan + 15 orta + 12 cetin.
--  ext_key: edeb11-...
--  ON SERT: 58_movzular_edebiyyat9_10.sql islenmis olmalidir.
--  SONRA:   05_grants.sql yeniden islet.
-- =====================================================================

do $$
begin
  if not exists (select 1 from public.topics t join public.subjects s
      on s.id = t.subject_id
     where s.slug = 'edebiyyat' and t.slug in
           ('edeb-10-sifahi', 'edeb-10-maarifci')
     having count(*) = 2) then
    raise exception 'ONCE 58_movzular_edebiyyat9_10.sql isledilmelidir.';
  end if;
end $$;

delete from public.question_options o
 using public.questions q
 where o.question_id = q.id
   and q.owner_type = 'platform'
   and q.ext_key like 'edeb10-%';

